import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"Interface: LaunchOptions","description":"","frontmatter":{},"headers":[],"relativePath":"api/spool/interfaces/LaunchOptions.md","filePath":"api/spool/interfaces/LaunchOptions.md"}'),c={name:"api/spool/interfaces/LaunchOptions.md"};function l(s,e,r,n,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<p><a href="./../">spool</a> / LaunchOptions</p><h1 id="interface-launchoptions" tabindex="-1">Interface: LaunchOptions <a class="header-anchor" href="#interface-launchoptions" aria-label="Permalink to &quot;Interface: LaunchOptions&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/ballistics/launch.ts#L19" target="_blank" rel="noreferrer">plugins/ballistics/launch.ts:19</a></p><p>Options for finding a launch that hits a target.</p><p>Flight time is the only free choice: for each time, the velocity that hits exactly is one division (see <code>physics.ts</code>). So the solver lists exact solutions and filters them by your constraints, rather than searching.</p><p>Whole ticks by default, so TNT with <code>fuse = ticks</code> explodes right on target.</p><p>Known differences from the game: no block collision, ground bounce or fluids; entities summoned mid-tick start moving next tick; TNT explodes 0.0625 above its feet; aim at feet; unloaded chunks don&#39;t tick; arrows fired by mobs get random spread.</p><h2 id="extended-by" tabindex="-1">Extended by <a class="header-anchor" href="#extended-by" aria-label="Permalink to &quot;Extended by&quot;">​</a></h2><ul><li><a href="./BallisticOptions.html"><code>BallisticOptions</code></a></li></ul><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="maxspeed" tabindex="-1">maxSpeed? <a class="header-anchor" href="#maxspeed" aria-label="Permalink to &quot;maxSpeed?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>maxSpeed?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/ballistics/launch.ts#L25" target="_blank" rel="noreferrer">plugins/ballistics/launch.ts:25</a></p><p>Reject faster solutions, in blocks/tick. Default 10, vanilla&#39;s Motion limit.</p><hr><h3 id="maxticks" tabindex="-1">maxTicks? <a class="header-anchor" href="#maxticks" aria-label="Permalink to &quot;maxTicks?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>maxTicks?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/ballistics/launch.ts#L32" target="_blank" rel="noreferrer">plugins/ballistics/launch.ts:32</a></p><p>Latest flight time. Defaults to the projectile&#39;s fuse (80 for TNT), so it doesn&#39;t explode early.</p><hr><h3 id="minspeed" tabindex="-1">minSpeed? <a class="header-anchor" href="#minspeed" aria-label="Permalink to &quot;minSpeed?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>minSpeed?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/ballistics/launch.ts#L23" target="_blank" rel="noreferrer">plugins/ballistics/launch.ts:23</a></p><p>Reject solutions slower than this, in blocks/tick. Default <code>0</code>.</p><hr><h3 id="minticks" tabindex="-1">minTicks? <a class="header-anchor" href="#minticks" aria-label="Permalink to &quot;minTicks?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>minTicks?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/ballistics/launch.ts#L27" target="_blank" rel="noreferrer">plugins/ballistics/launch.ts:27</a></p><p>Earliest allowed flight time, in ticks. Default <code>1</code>.</p><hr><h3 id="pitchrange" tabindex="-1">pitchRange? <a class="header-anchor" href="#pitchrange" aria-label="Permalink to &quot;pitchRange?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>pitchRange?</strong>: readonly [<code>number</code>, <code>number</code>]</p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/ballistics/launch.ts#L37" target="_blank" rel="noreferrer">plugins/ballistics/launch.ts:37</a></p><p>Launch angle range in degrees, negative is up. <code>[-90, -45]</code> for a lob, <code>[-20, 0]</code> for a flat shot.</p><hr><h3 id="prefer" tabindex="-1">prefer? <a class="header-anchor" href="#prefer" aria-label="Permalink to &quot;prefer?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>prefer?</strong>: <code>&quot;min-speed&quot;</code> | <code>&quot;min-time&quot;</code> | <code>&quot;max-time&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/ballistics/launch.ts#L44" target="_blank" rel="noreferrer">plugins/ballistics/launch.ts:44</a></p><p>Which exact solution to return:</p><ul><li><code>&quot;min-speed&quot;</code> (default): slowest shot that reaches.</li><li><code>&quot;min-time&quot;</code>: flattest and fastest.</li><li><code>&quot;max-time&quot;</code>: highest lob that fits; clears walls.</li></ul><hr><h3 id="projectile" tabindex="-1">projectile? <a class="header-anchor" href="#projectile" aria-label="Permalink to &quot;projectile?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>projectile?</strong>: <a href="./ProjectileProfile.html"><code>ProjectileProfile</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/ballistics/launch.ts#L21" target="_blank" rel="noreferrer">plugins/ballistics/launch.ts:21</a></p><p>Which entity to model. Default PROJECTILES.tnt.</p><hr><h3 id="subticksamples" tabindex="-1">subTickSamples? <a class="header-anchor" href="#subticksamples" aria-label="Permalink to &quot;subTickSamples?&quot;">​</a></h3><blockquote><p><code>readonly</code> <code>optional</code> <strong>subTickSamples?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/spool/src/plugins/ballistics/launch.ts#L49" target="_blank" rel="noreferrer">plugins/ballistics/launch.ts:49</a></p><p>Flight times tried per tick. Default <code>1</code>. Raise for projectiles that must arrive between ticks.</p>',50)])])}const u=o(c,[["render",l]]);export{b as __pageData,u as default};
